//! 🏦️ Actual finite Source work and physical authorities are shared by native construction laws.
use semio_framework_value_control_contract::*;
use semio_framework_value_native_decoding::NativeDecodeControl;
use std::sync::{Arc,Mutex};
pub(crate) struct Wallet{pub(crate) left:RetainedCloneGrant,pub(crate) fuel:u128,pub(crate) spent:RetainedCloneProgress,pub(crate) partials:usize,pub(crate) post_calls:usize,pub(crate) deny:bool,pub(crate) reject:bool,pub(crate) work_error:Option<ValueError>,pub(crate) post_error:Option<ValueError>}
struct Work{source:Arc<OriginalSourceTurnIssuer>,wallet:Arc<Mutex<Wallet>>}
impl OriginalWorkRecipient for Work{
 type Context<'turn,'source>=&'turn OriginalSourceTurn where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{self.source.validate(c).map_err(Into::into)}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(c.identity())}
 fn admits<'a,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,quote:OriginalWorkQuote<'a>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'a>where 'source:'turn{let wallet=self.wallet.lock().unwrap();quote.complete(Ok(observed.checked_add(additional).is_some_and(|total|u128::from(total)<=wallet.fuel)))}
 fn settle_partial<'a,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,reply:OriginalWorkPartialCheck<'a>)->OriginalWorkPartialCheckComplete<'a>where 'source:'turn{let valid=self.validate_context(c);let mut wallet=self.wallet.lock().unwrap();wallet.fuel=wallet.fuel.checked_sub(reply.delta()).unwrap();wallet.partials+=1;let result=match valid{Err(error)=>Err(error),Ok(())=>match wallet.work_error.take(){Some(error)=>Err(error),None=>Ok(())}};reply.complete(result)}
 fn recover_partial<'a,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,reply:OriginalWorkPartialCheck<'a>)->OriginalWorkPartialCheckComplete<'a>where 'source:'turn{reply.pending()}
}
struct Physical{source:Arc<OriginalSourceTurnIssuer>,wallet:Arc<Mutex<Wallet>>,interrupt:bool,interrupt_copy:Arc<std::sync::atomic::AtomicBool>}
impl OriginalConstructionRecipient for Physical{
 type Context<'turn,'source>=&'turn OriginalSourceTurn where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{self.source.validate(c).map_err(Into::into)}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(c.identity())}
 fn grant<'a,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,reply:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a>where 'source:'turn{let left=self.wallet.lock().unwrap().left;let d=reply.demand();reply.complete(Ok(if !self.wallet.lock().unwrap().deny&&retained_clone_grant_admits(left,d){RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}else{Default::default()}))}
 fn accept<'a,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,reply:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a>where 'source:'turn{let p=reply.progress();let mut wallet=self.wallet.lock().unwrap();wallet.post_calls+=1;assert!(p.fits(reply.grant())&&p.fits(wallet.left),"original physical progress {p:?} exceeds grant {:?} or Source stock {:?}",reply.grant(),wallet.left);wallet.left.maximum_items-=p.copied_items;wallet.left.maximum_copy_bytes-=p.copied_bytes;wallet.left.maximum_capacity_bytes-=p.retained_capacity_bytes;wallet.left.maximum_release_bytes-=p.released_bytes;wallet.spent=wallet.spent.checked_add(p).unwrap();let reject=wallet.reject;let post_error=wallet.post_error.take();drop(wallet);let recorded=reply.complete(match post_error{Some(error)=>Err(error),None if reject=>Err(ValueError::literal(ValueRefusalKind::WorkLimit,"actual construction recipient refused receipt")),None=>Ok(())});if self.interrupt&&p.retained_capacity_bytes!=0{self.interrupt=false;panic!("original Source recorded the constructor receipt")}if p.copied_bytes!=0&&self.interrupt_copy.swap(false,std::sync::atomic::Ordering::SeqCst){panic!("original Source recorded the terminal copy receipt")}recorded}
 fn submitted<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->RetainedCloneProgress where 'source:'turn{self.wallet.lock().unwrap().spent}
}
pub(crate) struct Bank{pub(crate) source:Arc<OriginalSourceTurnIssuer>,pub(crate) turn:Arc<OriginalSourceTurn>,pub(crate) wallet:Arc<Mutex<Wallet>>,pub(crate) interrupt_copy:Arc<std::sync::atomic::AtomicBool>,work:Option<OriginalWorkAuthority<Work>>,physical:OriginalConstructionAuthority<Physical>}
impl Bank{
 pub(crate) fn from_stock(stock:&serde_json::Value,interrupt:bool)->Self{let source=Arc::new(OriginalSourceTurnIssuer::new());let turn=Arc::new(source.issue().unwrap());let wallet=Arc::new(Mutex::new(Wallet{left:RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize},fuel:u128::from(stock["fuel"].as_u64().unwrap()),spent:Default::default(),partials:0,post_calls:0,deny:false,reject:false,work_error:None,post_error:None}));let interrupt_copy=Arc::new(std::sync::atomic::AtomicBool::new(false));Self{source:source.clone(),turn,wallet:wallet.clone(),interrupt_copy:interrupt_copy.clone(),work:Some(OriginalWorkAuthority::new(Work{source:source.clone(),wallet:wallet.clone()})),physical:OriginalConstructionAuthority::new(Physical{source,wallet,interrupt,interrupt_copy})}}
 pub(crate) fn sibling_authority(&self)->Self{Self{source:self.source.clone(),turn:self.turn.clone(),wallet:self.wallet.clone(),interrupt_copy:self.interrupt_copy.clone(),work:Some(OriginalWorkAuthority::new(Work{source:self.source.clone(),wallet:self.wallet.clone()})),physical:OriginalConstructionAuthority::new(Physical{source:self.source.clone(),wallet:self.wallet.clone(),interrupt:false,interrupt_copy:self.interrupt_copy.clone()})}}
 pub(crate) fn run<T>(&mut self,native:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<T,ValueError>{self.run_with_turn(native,|_,native|operation(native))}
 pub(crate) fn run_with_turn<T>(&mut self,native:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&OriginalSourceTurn,&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<T,ValueError>{let turn=self.turn.as_ref();let mut physical_context=turn;let physical=&mut self.physical;if let Some(work)=self.work.as_mut(){let mut work_context=turn;work.with_loan(&mut work_context,|work|native.with_work_recipient(work,|native|physical.with_loan(&mut physical_context,|physical|native.with_construction_recipient(physical,|native|operation(turn,native)))?))?}else{physical.with_loan(&mut physical_context,|physical|native.with_construction_recipient(physical,|native|operation(turn,native)))?}}

 pub(crate) fn run_frame<T>(&mut self,frame:&mut semio_framework_value_native_decoding::NativeDecodeFrame,recipient:Option<&mut semio_framework_value_native_decoding::NativeDecodeRetirementRecipient>,progress:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool,operation:impl FnOnce(&mut Bank,&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<T,semio_framework_value_native_decoding::NativeCallFailure<T,ValueError>>{
  struct Restore<'a>{bank:&'a mut Bank,work:Option<OriginalWorkAuthority<Work>>}
  impl Drop for Restore<'_>{fn drop(&mut self){self.bank.work=self.work.take()}}
  let work=self.work.take();let mut restore=Restore{bank:self,work};let turn=restore.bank.turn.clone();let mut context=turn.as_ref();restore.work.as_mut().expect("actual Work authority is resident").with_loan(&mut context,|loan|match recipient{Some(recipient)=>frame.decode_with_retirement(recipient,loan,progress,|native|operation(restore.bank,native)),None=>frame.decode(loan,progress,|native|operation(restore.bank,native))}).map_err(|error|semio_framework_value_native_decoding::NativeCallFailure{output:None,operation:None,context:Some(error),receipt_refusal:None})?
 }

 pub(crate) fn with_terminal_loans<T>(&mut self,operation:impl FnOnce(&mut OriginalWorkLoan<'_>,&mut OriginalConstructionLoan<'_>)->Result<T,ValueError>)->Result<T,ValueError>{let turn=self.turn.as_ref();let mut work_context=turn;let mut physical_context=turn;let physical=&mut self.physical;self.work.as_mut().expect("actual Work authority retained").with_loan(&mut work_context,|work|physical.with_loan(&mut physical_context,|physical|operation(work,physical))?)?}

 pub(crate) fn finish_frame(&mut self,handoff:&mut semio_framework_value_native_decode_handoff::NativeDecodeFrameHandoff,frame:&mut Option<semio_framework_value_native_decoding::NativeDecodeFrame>,recipient:&mut Option<semio_framework_value_native_decoding::NativeDecodeRetirementRecipient>,output:&mut semio_framework_value_native_decode_handoff::NativeDecodeFrameTerminalOutput,progress:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool)->Result<bool,semio_framework_value_native_decoding::NativeCallFailure<bool,ValueError>>{let turn=self.turn.as_ref();let mut work_context=turn;let mut physical_context=turn;let physical=&mut self.physical;let refused=|error|semio_framework_value_native_decoding::NativeCallFailure{output:None,operation:None,context:Some(error),receipt_refusal:None};self.work.as_mut().expect("actual Work authority retained").with_loan(&mut work_context,|work|physical.with_loan(&mut physical_context,|physical|handoff.drive(frame,recipient,output,work,physical,progress)).map_err(refused)?).map_err(refused)?}

 pub(crate) fn retire_frame_output(&mut self,handoff:&mut semio_framework_value_native_decode_handoff::NativeDecodeFrameHandoff,output:&mut semio_framework_value_native_decode_handoff::NativeDecodeFrameTerminalOutput,progress:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool)->Result<bool,semio_framework_value_native_decoding::NativeCallFailure<bool,ValueError>>{let turn=self.turn.as_ref();let mut work_context=turn;let mut physical_context=turn;let physical=&mut self.physical;let refused=|error|semio_framework_value_native_decoding::NativeCallFailure{output:None,operation:None,context:Some(error),receipt_refusal:None};self.work.as_mut().expect("actual Work authority retained").with_loan(&mut work_context,|work|physical.with_loan(&mut physical_context,|physical|handoff.retire_output(output,work,physical,progress)).map_err(refused)?).map_err(refused)?}

 pub(crate) fn transfer_terminal_failure(&mut self,handoff:&mut semio_framework_value_native_decode_handoff::NativeDecodeFrameHandoff,output:&mut semio_framework_value_native_decode_handoff::NativeTerminalFailureOutput,progress:&mut dyn FnMut(semio_framework_value_native_decoding::NativeDecodeProgress)->bool)->Result<bool,semio_framework_value_native_decoding::NativeCallFailure<bool,ValueError>>{let turn=self.turn.as_ref();let mut work_context=turn;let mut physical_context=turn;let physical=&mut self.physical;let refused=|error|semio_framework_value_native_decoding::NativeCallFailure{output:None,operation:None,context:Some(error),receipt_refusal:None};self.work.as_mut().expect("actual Work authority retained").with_loan(&mut work_context,|work|physical.with_loan(&mut physical_context,|physical|handoff.transfer_failure(output,work,physical,progress)).map_err(refused)?).map_err(refused)?}

}
